const assert = require('assert');
const UnusedCSSAudit = require('../../../audits/byte-efficiency/unused-css-rules.js');

function testUnusedCSSAudit() {
  const networkRecords = [
    {
      url: 'http://example.com/style.css',
      transferSize: 80 * 1024, // 80KB
      resourceType: 'Stylesheet',
    },
  ];

  const CSSUsage = {
    rules: [
      {styleSheetId: '1', used: false},
    ],
    stylesheets: [
      {
        header: {styleSheetId: '1', sourceURL: 'http://example.com/style.css'},
        content: 'body { overflow: hidden !important; }',
      },
    ],
  };

  const artifacts = {
    devtoolsLogs: {defaultPass: []},
    URL: {finalUrl: 'http://example.com'},
    CSSUsage,
  };

  return UnusedCSSAudit.audit_(artifacts, networkRecords).then(result => {
    assert.equal(result.items.length, 1);
    assert.equal(result.items[0].totalBytes, 80 * 1024);
    assert.equal(result.items[0].wastedPercent, 87.5); // 70KB savings
  });
}

testUnusedCSSAudit();
